abstract class AOBase { public abstract String tag(); }
class Sub extends AOBase { public String tag() { return 'abstract-tag'; } }
Object r; String observed;
try {
AOBase p=new Sub(); r=p.tag();
observed=String.valueOf(r);
} catch(Exception e) {
observed='EXC|'+e.getTypeName()+'|'+e.getMessage();
}
System.assert(false,'P|R001|'+observed);

