public with sharing class BRPC09Holder {
    private abstract class Token {
        public abstract Type getType();
    }
    public class Gold extends Token {
        public final Integer value;
        public Gold(Integer value) {
            this.value = value;
        }
        public Type getType() {
            return Gold.class;
        }
        public override String toString() {
            return 'Gold#' + value;
        }
        public Boolean equals(Object obj) {
            if (obj === this) {
                return true;
            }
            if (!(obj instanceof Gold)) {
                return false;
            }
            Gold that = (Gold) obj;
            return this.value == that.value;
        }
        public Integer hashCode() {
            Integer result = 1;
            result = 31 * result + System.hashCode(this.value);
            return result;
        }
    }
    public class Plain extends Token {
        public Type getType() {
            return Plain.class;
        }
        public override String toString() {
            return 'Plain';
        }
        public Boolean equals(Object obj) {
            if (obj === this) {
                return true;
            }
            return (obj instanceof Plain);
        }
        public Integer hashCode() {
            return 'Plain'.hashCode();
        }
    }
    private static Integer valueOf(Token t) {
        if (t.getType() == Gold.class) {
            return ((Gold) t).value;
        } else if (t.getType() == Plain.class) {
            return 0;
        } else {
            return null;
        }
    }
    public static Integer total() {
        return valueOf(new Gold(7)) + valueOf(new Plain());
    }
}

